import{z as i,x as l,o as E,c as p,q as n,j as o,D as e,d as r,s,S as A,b as B}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"跨资产价值与动量","description":"","frontmatter":{"title":"跨资产价值与动量","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/value-momentum-everywhere.md","filePath":"quant/value-momentum-everywhere.md","lastUpdated":1791413859000}'),m={name:"quant/value-momentum-everywhere.md"};function d(h,a,u,D,C,M){const t=l("Mermaid");return E(),p("div",null,[a[2]||(a[2]=n('<h1 id="跨资产价值与动量" tabindex="-1">跨资产价值与动量 <a class="header-anchor" href="#跨资产价值与动量" aria-label="Permalink to &quot;跨资产价值与动量&quot;">​</a></h1><div class="epigraph"><p>价值与动量不仅存在于美股，也存在于国际股票、股指、外汇、国债与商品；两者在各类内部负相关，合在一起的夏普远高于单独一条腿。</p><footer>—— Asness, Moskowitz &amp; Pedersen, Value and Momentum Everywhere, Journal of Finance, 2013</footer></div><p><a href="/quant/tsmom">上一课</a>把动量写成期货自身的趋势符号。股票里的价值是 <a href="/quant/value-factors">B/M、E/P、CF/P</a>，动量是 <a href="/quant/momentum-wml">12−1 WML</a>。Asness、Moskowitz、Pedersen 把同一对风格搬到八个市场：美股、英国、欧洲、日本个股，以及全球股指、外汇、国债、商品。非股票资产没有账面股权，价值改用长期反转一类的「便宜」代理；动量仍用过去约一年的相对收益。本文的贡献不是再发现美股 HML，而是：<strong>风格是跨资产的，负相关也是跨资产的</strong>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若价值溢价只是美股会计与 Compact Disclosure 样本的产物，它就很难当风险因子。若动量只是散户对个股消息反应不足，它就不该出现在外汇与商品里。AMP 要检验的是风格是否「到处都在」。同时，股票里价值与动量负相关是配置事实：<a href="/quant/hml-devil">HML Devil</a> 还说明负相关强弱取决于价值时效。若在商品、外汇里也能看到「便宜的继续便宜的对立面是最近的赢家」，则分散化不是美股特有的偶然。</p><p>第二个问题是共同因子。若各国价值在同一月一起赚、一起亏，就存在全球风格风险，而不是互不相关的国家异常。原文用全球资金流动性等宏观变量去看价值、动量的共同变动。这为后来把风格写进多资产风险模型提供了实证许可。</p><h3 id="非股票的「价值」是什么" tabindex="-1">非股票的「价值」是什么 <a class="header-anchor" href="#非股票的「价值」是什么" aria-label="Permalink to &quot;非股票的「价值」是什么&quot;">​</a></h3><p>个股：B/M（可用当期价格，接近 Devil）。股指：国家或指数层面的 B/M 或股利收益率。外汇：长期实际汇率偏离、或五年过去收益的反转（高利率货币若已大涨则不再「便宜」）。国债：真实债券收益率或相对期限结构的偏离。商品：现货相对长期均价、或五年反转。这些度量不统一，原则统一：<strong>价格相对于缓慢基本面或相对于自身长期历史是否低</strong>。五年反转是最脏但最可移植的定义，它与动量的形成期必须错开，否则两条腿数学上接近负号。</p><p><span class="marginnote">数字实例：动量看过去 12 个月，反转看过去 5 年——时间窗必须错开。若把反转也改成过去 1 年，它就变成动量的负号：买「近一年输家」正是动量策略的空头腿，两条腿互相抵消，组合什么都不剩。错开到五年，量才是不同时间尺度的行为。</span></p><p><span class="marginnote">日本个股是著名的例外：价值长期有效，截面动量弱甚至为负。原文仍把日本放进全球价值、全球动量组合。单看日本动量「不存在」而否定 everywhere，忽略了组合在其他市场的证据，也忽略了价值-动量在日本仍可能负相关。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每个市场内部：按价值度量排序做多空，按 12−1（或类似）动量排序做多空，价值加权或等权视资产流动性而定。再把各国/各资产的价值腿合成「全球价值」，动量腿合成「全球动量」。关键统计量是：各市场溢价的均值与 t 值、价值与动量的相关矩阵（市场内与市场间）、50/50 组合相对单腿的夏普提升。</p> \\[r_t^{50/50}=\\tfrac12 r_t^{\\mathrm{VAL}}+\\tfrac12 r_t^{\\mathrm{MOM}} \\]<p>在负相关下方差下降多于均值牺牲。时效：价值若用陈旧价格，与动量的对冲变弱，50/50 的好处会被低估或高估。应与 Devil 的原则一致：基本面滞后、价格尽量新。动量在非股票上通常不必跳月，但商品有展期收益，须把展期从「动量」里讲清楚，避免与<a href="/quant/carry-everywhere">Carry</a> 双计。</p><p><span class="marginnote">直觉类比：负相关的两条腿像两位轮班司机，一位犯困时另一位正好清醒，车队整体比任何一位单独开都平稳。但两人走的是同一条山路——融资踩踏来临时是「整条路塌方」，谁也替不了谁，所以 50/50 降的是平常月份的波动，不是尾部。</span></p><h3 id="市场间相关-风格风险而不是国家风险" tabindex="-1">市场间相关：风格风险而不是国家风险 <a class="header-anchor" href="#市场间相关-风格风险而不是国家风险" aria-label="Permalink to &quot;市场间相关：风格风险而不是国家风险&quot;">​</a></h3><p>各国价值腿彼此正相关，各国动量腿彼此正相关，价值与动量跨市场仍常为负。这意味着有一种全球「价值因子」和全球「动量因子」，而不是 8 个独立赌局。资金流动性收紧时，杠杆投资者同时削减动量等多空，动量崩溃可以全球同步；价值有时在此时作为对手盘赚钱，有时一起被砸（去杠杆不看风格）。配置上，50/50 降低的是平常月份的波动，不一定降低融资踩踏的尾部。</p>',17)),(E(),o(A,null,{default:e(()=>[s(t,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20STK%5B%22%E4%B8%AA%E8%82%A1%20B%2FM%22%5D%20--%3E%20VAL%5B%22%E5%90%84%E5%B8%82%E5%9C%BA%E4%BB%B7%E5%80%BC%E5%A4%9A%E7%A9%BA%22%5D%0A%20%20IDX%5B%22%E8%82%A1%E6%8C%87%20%2F%20%E6%B1%87%20%2F%20%E5%80%BA%20%2F%20%E5%95%86%E5%93%81%E7%9A%84%E9%95%BF%E6%9C%9F%E4%BE%BF%E5%AE%9C%22%5D%20--%3E%20VAL%0A%20%20MOM%5B%2212%E2%88%921%20%E7%9B%B8%E5%AF%B9%E5%BC%BA%E5%BA%A6%22%5D%20--%3E%20MO%5B%22%E5%90%84%E5%B8%82%E5%9C%BA%E5%8A%A8%E9%87%8F%E5%A4%9A%E7%A9%BA%22%5D%0A%20%20VAL%20--%3E%20GV%5B%22%E5%85%A8%E7%90%83%E4%BB%B7%E5%80%BC%22%5D%0A%20%20MO%20--%3E%20GM%5B%22%E5%85%A8%E7%90%83%E5%8A%A8%E9%87%8F%22%5D%0A%20%20GV%20--%3E%20NEG%5B%22%E5%B8%82%E5%9C%BA%E5%86%85%E4%B8%8E%E5%B8%82%E5%9C%BA%E9%97%B4%E8%B4%9F%E7%9B%B8%E5%85%B3%22%5D%0A%20%20GM%20--%3E%20NEG%0A%20%20NEG%20--%3E%20MIX%5B%2250%2F50%20%E9%A3%8E%E6%A0%BC%E7%BB%84%E5%90%88%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=B("h2",{id:"机制",tabindex:"-1"},[r("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=B("p",null,"行为：过度外推使贵的更贵（动量），缓慢基本面回归使便宜的最终胜出（价值）。同一群投资者可以同时制造两条异常，并因仓位拥挤而让它们负相关——刚被追涨的不会出现在价值多头里。风险：价值像困境与高久期生产资本，动量像增长期权与流动性需求；两种风险的价格可以异号。资金：动量是高换手、高杠杆策略，对融资更敏感；价值换手低，对融资的暴露不同，于是相关为负。",-1)),(E(),o(A,null,{default:e(()=>[s(t,{id:"mermaid-54",class:"mermaid",graph:"flowchart%20TD%0A%20%20Mom%5B%22%E5%8A%A8%E9%87%8F%E5%A4%9A%E5%A4%B4%E6%8C%81%E6%9C%89%E8%BF%91%E6%9C%9F%E8%B5%A2%E5%AE%B6%22%5D%20--%3E%20Crowded%5B%22%E4%BB%93%E4%BD%8D%E9%9B%86%E4%B8%AD%E5%9C%A8%E8%A2%AB%E8%BF%BD%E6%B6%A8%E7%9A%84%E4%B8%80%E6%89%B9%22%5D%0A%20%20Val%5B%22%E4%BB%B7%E5%80%BC%E5%A4%9A%E5%A4%B4%E6%8C%81%E6%9C%89%E5%86%B7%E8%90%BD%E4%BE%BF%E5%AE%9C%E8%B4%A7%22%5D%20--%3E%20Opp%5B%22%E4%BB%93%E4%BD%8D%E5%9C%A8%E8%BF%91%E6%9C%9F%E8%BE%93%E5%AE%B6%E4%B8%80%E4%BE%A7%22%5D%0A%20%20Crowded%20--%3E%20Disjoint%5B%22%E4%B8%A4%E7%BB%84%E6%8C%81%E4%BB%93%E5%87%A0%E4%B9%8E%E4%B8%8D%E9%87%8D%E5%8F%A0%22%5D%0A%20%20Opp%20--%3E%20Disjoint%0A%20%20Disjoint%20--%3E%20Neg%5B%22%E6%9C%88%E5%BA%A6%E6%94%B6%E7%9B%8A%E5%91%88%E8%B4%9F%E7%9B%B8%E5%85%B3%22%5D%0A%20%20Funding%5B%22%E8%9E%8D%E8%B5%84%E6%9D%A1%E4%BB%B6%E6%94%B6%E7%B4%A7%22%5D%20--%3E%20Crash%5B%22%E5%8A%A8%E9%87%8F%E8%85%BF%E5%85%A8%E7%90%83%E5%90%8C%E6%AD%A5%E5%8E%BB%E6%9D%A0%E6%9D%86%22%5D%0A%20%20Neg%20--%3E%20Mix%5B%2250%2F50%20%E5%B9%B3%E5%B8%B8%E6%9C%88%E4%BB%BD%E6%B3%A2%E5%8A%A8%E6%9B%B4%E4%BD%8E%22%5D%0A%20%20Crash%20--%3E%20Tail%5B%22%E5%B0%BE%E9%83%A8%E4%BB%8D%E5%8F%AF%E8%83%BD%E4%B8%A4%E8%85%BF%E5%90%8C%E8%B7%8C%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=n('<p><span class="marginnote">常见误区：以为价值-动量负相关是有人刻意设计的「对冲」。没有人安排——负相关是自然结果：动量买进的正是价值卖出的那批股票，两组持仓天然错开，所以一个亏的月份另一个常常在赚。</span></p><p>原文并不裁决哪一条机制唯一正确。它提供的约束是：机制必须能同时解释股票与非股票、必须允许负相关、必须允许全球共同变动。只解释美股应计的故事不够；只解释商品套保的故事也不够。</p><h3 id="与-tsmom、carry-的边界" tabindex="-1">与 TSMOM、Carry 的边界 <a class="header-anchor" href="#与-tsmom、carry-的边界" aria-label="Permalink to &quot;与 TSMOM、Carry 的边界&quot;">​</a></h3><p><a href="/quant/tsmom">时间序列动量</a> 用绝对趋势，AMP 的动量主要是截面相对强度。期货池上两者相关，但净暴露不同。Carry 是「价格不变时的收益」，价值是「价格相对基本面偏低」。高 Carry 的货币可以很贵（已升值），高价值的货币可以低 Carry。三因子风格——价值、动量、Carry——应分开报告，再看相关，而不是把商品的 backwardation 既当价值又当动量又当 Carry。</p><p><span class="marginnote">everywhere 不是「每个市场每个十年都显著」。单市场 t 值可以平凡，联合与合成才强。用某一个十年的外汇动量崩溃否定 2013 年论文，与用日本动量弱否定它，是同一类以偏概全。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>交易成本：个股动量贵，商品与外汇动量相对便宜；价值在个股上便宜，在商品上「五年反转」换手也不低。容量：全球个股价值加权远大于商品截面。数据：国债与商品的价值代理有研究自由度，预注册排序规则，避免为 everywhere 而挑选度量。A 股可作为又一个股票市场加入，但涨跌停与融券会改动量空头，不能直接套用欧洲的换手假设。</p><p>不要把 AMP 的全球动量叫做 Moskowitz–Ooi–Pedersen 的 TSMOM。不要把五年反转叫做 HML。不要在回归里同时放各国 HML 再放「全球价值」声称多个 α。实施 50/50 时两边的波动往往不同，应按风险预算而不是名义资金 50/50，否则动量腿会主导。</p><p><span class="marginnote">出处：Asness, Moskowitz &amp; Pedersen, <em>Value and Momentum Everywhere</em>, Journal of Finance, 2013。HML 时效见 Asness &amp; Frazzini, 2013。TSMOM 见 Moskowitz, Ooi &amp; Pedersen, 2012。Carry 见 Koijen 等, 2018。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>价值与动量在个股与多种期货/外汇/国债上重复出现。</li><li>市场内及市场间，两者常负相关；50/50 提升夏普，但不自动消灭融资尾部。</li><li>非股票价值需可移植代理，并与动量形成期错开。</li><li>与 TSMOM、Carry 分工，避免把展期收益三记。</li><li>出处：Asness, Moskowitz &amp; Pedersen, Journal of Finance, 2013。</li></ul>',11))])}const F=i(m,[["render",d]]);export{f as __pageData,F as default};
